class Customer {
  + address : string
  + vat_number : string
  + head_office_address : string
}

class Product {
  + name : string
  + stock_level : int
}

class Order {
  + order_date : date
  + payment_date : date
  + is_paid : boolean
}

class OrderLine {
  + quantity : int
}

class Shipment {
  + status : string
}

class Delivery {
  + status : string
}

class Invoice {
}

class Warehouse {
  + address : string
}

class DeliveryAddress {
  + address : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Customer "1" -- "*" DeliveryAddress : deliversTo
Customer "1" -- "*" Warehouse : owns
Order "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Product : refersTo
Order "1" -- "0..*" Invoice : billedBy
Order "1" -- "0..*" Shipment : splitInto
Shipment "1" *-- "1..*" OrderLine : contains
Shipment "1" -- "0..1" Delivery : resultsIn
Delivery "1" -- "1..*" OrderLine : covers

@enduml

